import{_ as o,o as r,c as d,a2 as a}from"./chunks/framework.DGvnA5EY.js";const e="/workbuddy-guide/assets/01-antivirus-blocks-installer.BoBhsXlk.png",g=JSON.parse('{"title":"第 2 章 下载、安装、登录与更新","description":"> 内容来源：WorkBuddy 官方指南 + 官方安装流程（非官方整理，© 本指南作者，保留所有权利） 上一章你知道了 WorkBuddy 能干什么。这一章把它装到电脑上——从下载到登录， 全程大约 10 分钟。这一章的目标很单纯：装完、登进去、确认能用。","frontmatter":{"title":"第 2 章 下载、安装、登录与更新"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 2 章 下载、安装、登录与更新/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 2 章 下载、安装、登录与更新/index.md","lastUpdated":1791615980000}'),n={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 2 章 下载、安装、登录与更新/index.md"};function l(s,t,i,u,p,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="第-2-章-下载、安装、登录与更新" tabindex="-1">第 2 章 下载、安装、登录与更新 <a class="header-anchor" href="#第-2-章-下载、安装、登录与更新" aria-label="Permalink to &quot;第 2 章 下载、安装、登录与更新&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 + 官方安装流程（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>上一章你知道了 WorkBuddy 能干什么。这一章把它装到电脑上——从下载到登录， 全程大约 10 分钟。这一章的目标很单纯：<strong>装完、登进去、确认能用</strong>。</p><h2 id="一、先看硬件要求-别装完才发现带不动" tabindex="-1">一、先看硬件要求，别装完才发现带不动 <a class="header-anchor" href="#一、先看硬件要求-别装完才发现带不动" aria-label="Permalink to &quot;一、先看硬件要求，别装完才发现带不动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10 及以上 / macOS 12 及以上</td></tr><tr><td>内存</td><td>建议 8GB 以上</td></tr><tr><td>硬盘剩余</td><td>至少预留 3GB（含后续缓存）</td></tr><tr><td>网络</td><td>稳定即可，安装包约 150–180MB</td></tr></tbody></table><p><strong>为什么强调这个？</strong> 安装包本身不算大，但 WorkBuddy 会在本地缓存文件、 生成中间产物。磁盘空间太紧的话，运行到一半报「空间不足」，比装不上更闹心。</p><h2 id="二、下载-从官网拿-别从搜索结果里随便点" tabindex="-1">二、下载：从官网拿，别从搜索结果里随便点 <a class="header-anchor" href="#二、下载-从官网拿-别从搜索结果里随便点" aria-label="Permalink to &quot;二、下载：从官网拿，别从搜索结果里随便点&quot;">​</a></h2><p><strong>正确做法</strong>：浏览器打开 WorkBuddy 官网首页，页面会自动识别你的系统 （Windows 或 macOS），点「下载 WorkBuddy」按钮即可。</p><p><strong>为什么要认准官网？</strong> 市面上模仿官方界面的下载站不少，装到非官方包，轻则 捆绑一堆无关软件，重则装到坏东西。认准官网是唯一有效的防护。</p><p><strong>顺手核对文件名</strong>：下载完成后，确认安装包名称与官方一致。Windows 一般是 <code>WorkBuddySetup.exe</code>，macOS 是 <code>WorkBuddy.dmg</code>。名字不对就别装，重新去官网下。</p><h2 id="三、windows-安装-7-步" tabindex="-1">三、Windows 安装：7 步 <a class="header-anchor" href="#三、windows-安装-7-步" aria-label="Permalink to &quot;三、Windows 安装：7 步&quot;">​</a></h2><ol><li>双击 <code>WorkBuddySetup.exe</code>，启动安装向导。</li><li>弹出「用户账户控制」询问是否允许更改设备，点**「是」**。</li><li>阅读许可协议，勾选「我同意此协议」，点「下一步」。</li><li><strong>选择安装路径</strong>。默认路径在 C 盘的 <code>AppData</code> 目录里。 <strong>建议点「浏览」改到 D 盘或 E 盘</strong>——C 盘留给系统和微信这类常用软件更划算。</li><li>确认开始菜单文件夹，保持默认，点「下一步」。</li><li><strong>勾选「创建桌面快捷方式」</strong>，下次双击桌面图标就能启动。</li><li>点「安装」，等进度条走完（大约 30 秒到 1 分钟），完成后点「完成」。</li></ol><blockquote><p>想省事的读者直接用默认路径也能跑，只是长期用会占系统盘空间。</p></blockquote><h2 id="四、macos-安装-3-步-注意-无法验证开发者" tabindex="-1">四、macOS 安装：3 步，注意&quot;无法验证开发者&quot; <a class="header-anchor" href="#四、macos-安装-3-步-注意-无法验证开发者" aria-label="Permalink to &quot;四、macOS 安装：3 步，注意&quot;无法验证开发者&quot;&quot;">​</a></h2><ol><li>双击 <code>WorkBuddy.dmg</code> 文件。</li><li>把 WorkBuddy 图标<strong>拖进「应用程序」文件夹</strong>。</li><li>首次打开时，如果系统弹出「无法验证开发者」，这是 macOS 的正常机制 （因为没有走付费的苹果开发者认证）。处理办法： 打开<strong>系统设置 → 隐私与安全性 → 通用</strong>，在底部找到提示，点**「仍要打开」**， 再确认一次即可。之后就不会再拦了。</li></ol><h2 id="五、一个坑-杀毒软件可能把官方安装包误判成风险程序" tabindex="-1">五、一个坑：杀毒软件可能把官方安装包误判成风险程序 <a class="header-anchor" href="#五、一个坑-杀毒软件可能把官方安装包误判成风险程序" aria-label="Permalink to &quot;五、一个坑：杀毒软件可能把官方安装包误判成风险程序&quot;">​</a></h2><p>这是新手安装失败最集中的原因。表现是：解压中途文件被删、安装到一半失败、 装完打不开。</p><p><strong>WorkBuddy 是腾讯官方认证的软件，本身没有病毒。</strong> 遇到这种情况， 在安装前临时关闭第三方杀毒软件和系统防火墙的拦截，装完立刻恢复防护即可。</p><p><img src="'+e+'" alt="杀毒软件误拦官方安装包，导致安装到一半失败" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解拦截环节，与实际软件界面无关。</em></p><p><strong>排查顺序</strong>（先做第 1 步，做完再考虑第 2 步）：</p><ol><li>先检查安装路径里有没有<strong>中文、空格或特殊字符</strong>——这是第二大原因。</li><li>路径没问题，再临时关闭防护试一次。</li></ol><h2 id="六、首次登录-三选一" tabindex="-1">六、首次登录：三选一 <a class="header-anchor" href="#六、首次登录-三选一" aria-label="Permalink to &quot;六、首次登录：三选一&quot;">​</a></h2><p>装完后会自动弹出登录界面，支持：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>微信扫码</td><td>最顺手，手机扫一下就进去了</td></tr><tr><td>QQ 扫码</td><td>已有 QQ 账号的话同样快</td></tr><tr><td>腾讯云账号</td><td>用腾讯云账号体系登录</td></tr></tbody></table><p>用哪个都行。<strong>扫码确认后会自动注册，并获得 5000 Credits 的初始额度。</strong></p><h2 id="七、别漏了文件夹授权-这是设计-不是-bug" tabindex="-1">七、别漏了文件夹授权（这是设计，不是 Bug） <a class="header-anchor" href="#七、别漏了文件夹授权-这是设计-不是-bug" aria-label="Permalink to &quot;七、别漏了文件夹授权（这是设计，不是 Bug）&quot;">​</a></h2><p>登录后你可能会看到一个要求授权文件夹的提示。<strong>这是安全设计，不是权限问题</strong>—— WorkBuddy 不会偷偷翻你全盘文件，它只在你明确授权的目录里干活。</p><p>建议授权一个专门的工作文件夹（比如新建一个 <code>WorkBuddy</code> 目录）， 而不是直接授权整个「文档」或「桌面」。原因很简单：授权范围越小， 它越不容易碰到你不想动的东西，出错时清理也简单。</p><h2 id="八、更新怎么弄" tabindex="-1">八、更新怎么弄 <a class="header-anchor" href="#八、更新怎么弄" aria-label="Permalink to &quot;八、更新怎么弄&quot;">​</a></h2><p>WorkBuddy 客户端一般会<strong>自动检查更新</strong>，有新版本会在界面上给出提示。 你也可以在设置里手动检查。</p><p><strong>为什么要及时更新？</strong> 官方迭代很快，新功能（比如某个专家、某个连接器） 经常是先在新版本里落地。旧版本看不到新功能，会以为是「这功能没有」。</p><h2 id="九、本章任务清单-做完就算过关" tabindex="-1">九、本章任务清单（做完就算过关） <a class="header-anchor" href="#九、本章任务清单-做完就算过关" aria-label="Permalink to &quot;九、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 从官网下载了安装包，文件名核对无误（<code>WorkBuddySetup.exe</code> / <code>WorkBuddy.dmg</code>）</li><li>[ ] 安装完成，桌面出现 WorkBuddy 快捷方式</li><li>[ ] 成功登录（扫码或账号），看到主界面</li><li>[ ] 授权了一个专门的工作文件夹（不是整个桌面）</li><li>[ ] 知道安装失败时先查「路径是否含中文空格」</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章出现了几个容易卡住的词，这里补一句人话解释，看不懂可以跳过正文直接看这里。</p></blockquote><p><strong>安装包 / 安装向导</strong> 下载下来的那个 <code>.exe</code> 或 <code>.dmg</code> 文件就是「安装包」，双击它之后弹出来的那一 步步界面就是「安装向导」。它只是把你确认几件事、复制几个文件，没有多复杂。</p><p><strong>用户账户控制（UAC）</strong> Windows 的安全机制。装任何软件它都会弹出来问「是否允许此应用对你的设备进行 更改」，点「是」就行。这个弹窗是<strong>系统的常规行为，不是中毒信号</strong>，可以放心点。</p><p><strong>「无法验证开发者」（macOS）</strong> 苹果要求付费开发者认证后才能免掉这个提醒。WorkBuddy 没走这个付费认证， 所以第一次打开会被拦。<strong>这不是盗版也不是病毒</strong>，按正文第四节的路径点 「仍要打开」就永久解决了。</p><p><strong>AppData</strong> C 盘里的一个隐藏文件夹，存放「这个用户的应用数据」。很多软件默认装在这儿， 软件本身不大但越攒越多。建议改到 D 盘就是为了给 C 盘减负。</p><p><strong>Credits</strong> WorkBuddy 内部使用的额度单位。可以理解成「AI 的工作点数」——你下的任务越多、 任务越复杂，消耗的点数越多。首次登录赠送 5000，够你用相当长一段时间。</p><p><strong>文件夹授权</strong> 你告诉 WorkBuddy「哪些目录你可以动」。它<strong>只能</strong>在你授权的目录里读写文件， 没授权的一律碰不到。所以授权范围越小越安全——这是保护你的机制，不是限制。</p><p><strong>系统防火墙 / 杀毒软件拦截</strong> 安全软件有时会把没见过的程序当成可疑对象，误拦或误删。WorkBuddy 是腾讯官方 认证的软件，可以放心放行；装完记得把防护重新打开。</p><hr><p><em>下一篇：第 3 章 主界面、任务与工作区——带你把左边那条导航栏彻底认熟。</em></p>',46)])])}const k=o(n,[["render",l]]);export{g as __pageData,k as default};
